import re

def slugify(text):
    return re.sub(r"\s+", "-", text.strip().lower())

export function initials(name: string): string {
    return name.trim().split(/\s+/).filter(Boolean).map((part) => part[0].toUpperCase()).join("");
}

static boolean isSorted(int[] values) {
    for (int i = 1; i < values.length; i++) {
        if (values[i] < values[i - 1]) return false;
    }
    return true;
}

#include <stddef.h>

size_t count_bytes(const char *text) {
    size_t length = 0;
    while (text[length] != '\0') length++;
    return length;
}

#include <vector>
#include <algorithm>

std::vector<int> rotate_left(std::vector<int> values) {
    if (!values.empty()) std::rotate(values.begin(), values.begin() + 1, values.end());
    return values;
}

from collections import Counter

def first_unique(text):
    counts = Counter(text)
    return next((char for char in text if counts[char] == 1), None)

function title_case(text) {
    return text.replace(/\S+/g, (word) => word[0].toUpperCase() + word.slice(1).toLowerCase());
}

export function unique<T>(values: T[]): T[] {
    return [...new Set(values)];
}

static int countVowels(String text) {
    int count = 0;
    for (int i = 0; i < text.length(); i++) {
        if ("aeiou".indexOf(Character.toLowerCase(text.charAt(i))) >= 0) count++;
    }
    return count;
}

fn is_palindrome(text: &str) -> bool {
    let filtered: Vec<u8> = text.bytes()
        .filter(u8::is_ascii_alphanumeric)
        .map(|byte| byte.to_ascii_lowercase())
        .collect();
    filtered.iter().eq(filtered.iter().rev())
}

#include <stddef.h>

long sum_array(const int *values, size_t length) {
    long sum = 0;
    for (size_t i = 0; i < length; i++) sum += values[i];
    return sum;
}

#include <sstream>
#include <string>

std::size_t word_count(const std::string& text) {
    std::istringstream input(text);
    std::size_t count = 0;
    std::string word;
    while (input >> word) count++;
    return count;
}
